import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Typography, 
  Button, 
  Card, 
  CardContent, 
  CardActions, 
  Divider, 
  LinearProgress, 
  TextField,
  IconButton,
  Menu,
  MenuItem,
  Avatar
} from '@mui/material';
import { MoreVert, ThumbUp, ThumbUpOutlined } from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import api from '../../utils/api';
import { formatDistanceToNow } from 'date-fns';

const Poll = ({ poll, onVote, onDelete }) => {
  const { user } = useAuth();
  const [selectedOption, setSelectedOption] = useState(null);
  const [hasVoted, setHasVoted] = useState(false);
  const [anchorEl, setAnchorEl] = useState(null);
  const [localPoll, setLocalPoll] = useState(poll);

  useEffect(() => {
    setLocalPoll(poll);
    // Check if user has already voted
    if (user) {
      const voted = poll.options.some(option => 
        option.voters.some(voter => voter.toString() === user.id)
      );
      setHasVoted(voted);
    }
  }, [poll, user]);

  const handleVote = async () => {
    if (selectedOption === null || hasVoted) return;
    
    try {
      const updatedPoll = await api.post(`/polls/${poll._id}/vote`, { 
        optionIndex: selectedOption 
      });
      setLocalPoll(updatedPoll);
      setHasVoted(true);
      if (onVote) onVote(updatedPoll);
    } catch (error) {
      console.error('Error voting:', error);
    }
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const handleDelete = async () => {
    handleMenuClose();
    if (onDelete) onDelete(poll._id);
  };

  const totalVotes = localPoll.options.reduce((sum, option) => sum + option.voters.length, 0);
  const isExpired = new Date(localPoll.expiresAt) < new Date();
  const canDelete = user && (user.isAdmin || user.id === localPoll.createdBy._id);

  return (
    <Card sx={{ mb: 3, borderRadius: 2, boxShadow: 3 }}>
      <CardContent>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Box display="flex" alignItems="center">
            <Avatar 
              src={localPoll.createdBy.avatar} 
              alt={localPoll.createdBy.username}
              sx={{ width: 40, height: 40, mr: 1 }}
            />
            <Box>
              <Typography variant="subtitle2">{localPoll.createdBy.username}</Typography>
              <Typography variant="caption" color="textSecondary">
                {formatDistanceToNow(new Date(localPoll.createdAt), { addSuffix: true })}
              </Typography>
            </Box>
          </Box>
          {canDelete && (
            <>
              <IconButton onClick={handleMenuOpen} size="small">
                <MoreVert />
              </IconButton>
              <Menu
                anchorEl={anchorEl}
                open={Boolean(anchorEl)}
                onClose={handleMenuClose}
              >
                <MenuItem onClick={handleDelete}>
                  Delete Poll
                </MenuItem>
              </Menu>
            </>
          )}
        </Box>

        <Typography variant="h6" gutterBottom>{localPoll.question}</Typography>
        {localPoll.description && (
          <Typography variant="body2" color="textSecondary" paragraph>
            {localPoll.description}
          </Typography>
        )}

        <Box mt={2}>
          {localPoll.options.map((option, index) => {
            const percentage = totalVotes > 0 
              ? Math.round((option.voters.length / totalVotes) * 100) 
              : 0;
            const isSelected = selectedOption === index;
            const hasVotedForOption = hasVoted && option.voters.some(voter => 
              user && voter.toString() === user.id
            );

            return (
              <Box 
                key={index} 
                mb={1.5}
                onClick={() => !hasVoted && !isExpired && setSelectedOption(index)}
                sx={{
                  p: 1.5,
                  borderRadius: 1,
                  border: '1px solid',
                  borderColor: isSelected ? 'primary.main' : 'divider',
                  backgroundColor: hasVotedForOption ? 'action.selected' : 'background.paper',
                  cursor: !hasVoted && !isExpired ? 'pointer' : 'default',
                  '&:hover': {
                    backgroundColor: !hasVoted && !isExpired ? 'action.hover' : 'inherit'
                  },
                  position: 'relative',
                  overflow: 'hidden'
                }}
              >
                <Box 
                  sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    height: '100%',
                    width: `${percentage}%`,
                    backgroundColor: 'primary.light',
                    opacity: 0.2,
                    zIndex: 0,
                    transition: 'width 0.5s ease'
                  }}
                />
                <Box position="relative" zIndex={1}>
                  <Box display="flex" justifyContent="space-between" alignItems="center">
                    <Typography variant="body1">
                      {option.text}
                      {hasVotedForOption && (
                        <ThumbUp color="primary" sx={{ ml: 1, fontSize: 16, verticalAlign: 'middle' }} />
                      )}
                    </Typography>
                    <Typography variant="body2" color="textSecondary">
                      {percentage}%
                    </Typography>
                  </Box>
                  {hasVoted && (
                    <LinearProgress 
                      variant="determinate" 
                      value={percentage} 
                      sx={{ mt: 1, height: 4, borderRadius: 2 }}
                    />
                  )}
                </Box>
              </Box>
            );
          })}
        </Box>

        <Box mt={2} display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="caption" color="textSecondary">
            {totalVotes} vote{totalVotes !== 1 ? 's' : ''} • 
            {isExpired 
              ? 'Poll ended' 
              : `Ends in ${formatDistanceToNow(new Date(localPoll.expiresAt), { addSuffix: true })}`
            }
          </Typography>
          
          {!isExpired && !hasVoted && (
            <Button 
              variant="contained" 
              color="primary" 
              onClick={handleVote}
              disabled={selectedOption === null}
              size="small"
            >
              Vote
            </Button>
          )}
        </Box>
      </CardContent>
    </Card>
  );
};

export default Poll;
